import { useEffect, useState, useCallback } from "react";
import axios from "axios";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend,
} from "chart.js";
import { Bar, Pie } from "react-chartjs-2";

// Register all needed components
ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  ArcElement,
  Tooltip,
  Legend
);

const API_URL = "http://localhost:5000";
const REFRESH_INTERVAL = 2000;

function AdminAnonymousResults({ theme }) {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchCandidates = useCallback(async () => {
    try {
      const { data } = await axios.get(`${API_URL}/api/candidates`);
      setCandidates(data);
    } catch (error) {
      console.error("Error fetching candidates:", error);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchCandidates();
    const interval = setInterval(fetchCandidates, REFRESH_INTERVAL);
    return () => clearInterval(interval);
  }, [fetchCandidates]);

  // Group candidates by position
  const groupedCandidates = candidates.reduce((acc, candidate) => {
    const position = candidate.candidacy || "Other";
    if (!acc[position]) acc[position] = [];
    acc[position].push(candidate);
    return acc;
  }, {});

  if (loading) {
    return <div style={{ padding: 20 }}>Loading results...</div>;
  }

  return (
    <div style={{ padding: "20px 30px" }}>
      <h2 style={{ marginBottom: 30 }}>Anonymous Election Monitor</h2>

      {Object.entries(groupedCandidates).map(([position, list]) => {
        const sortedCandidates = [...list].sort(
          (a, b) => (b.votes || 0) - (a.votes || 0)
        );

        const labels = sortedCandidates.map(
          (_, index) => `Candidate ${index + 1}`
        );
        const votes = sortedCandidates.map((c) => c.votes || 0);

        const colors = [
          "#cc2323",
          "#2196F3",
          "#FFC107",
          "#E91E63",
          "#9C27B0",
          "#FF5722",
          "#00BCD4",
        ];

        const commonDataset = {
          label: `${position} Votes`,
          data: votes,
          backgroundColor: colors,
        };

        const barData = {
          labels,
          datasets: [commonDataset],
        };

        const pieData = {
          labels,
          datasets: [commonDataset],
        };

        return (
          <div
            key={position}
            style={{
              marginBottom: 40,
              backgroundColor: theme.card || "#fff",
              padding: 20,
              borderRadius: 12,
              boxShadow: "0 4px 10px rgba(0,0,0,0.08)",
            }}
          >
            <h3 style={{ marginBottom: 20 }}>{position}</h3>

            {/* Charts container */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 20,
              }}
            >
              {/* Bar Chart */}
              <div>
                <Bar
                  data={barData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: { display: false },
                    },
                    scales: {
                      y: {
                        beginAtZero: true,
                        ticks: { precision: 0 },
                      },
                    },
                  }}
                />
              </div>

              {/* Pie Chart */}
              <div style={{ maxWidth: 400, margin: "0 auto" }}>
                <Pie
                  data={pieData}
                  options={{
                    responsive: true,
                    plugins: {
                      legend: {
                        position: "bottom",
                      },
                    },
                  }}
                />
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

export default AdminAnonymousResults;
